import { SegmentedControl, type SegmentedControlOption } from '@design-schema/rn';

const OPTIONS: SegmentedControlOption[] = [
  { value: 'list', label: 'List', icon: 'external' },
  { value: 'grid', label: 'Grid', icon: 'check' },
